// Stand-in for whatever decided the amount — an LLM, a price feed, a
// health-factor check. Agents get this wrong, and that is the point: the
// interesting question is what the execution layer does next.
//
// 999 ETH is deliberately more than the wallet holds.
return [{
  json: {
    reason: 'Position under threshold — repaying',
    recipient: '0x000000000000000000000000000000000000dEaD',
    amount: '999',
    attempt: 'first'
  }
}];

// The simulation gate stopped attempt 1 before any gas was spent, and the
// normalised error tells us why. Recalculate something the wallet can
// actually afford and try again — this is the recovery the audit trail
// should show.
const failure = $json.error ?? 'unknown';

return [{
  json: {
    recovered_from: failure.slice(0, 200),
    recipient: '0x000000000000000000000000000000000000dEaD',
    amount: '0.0001',
    attempt: 'retry'
  }
}];

// Nothing to recover from — attempt 1 landed. Shown for completeness so the
// canvas reads correctly in both directions.
return [{ json: { note: 'First attempt landed; no recovery needed', tx: $json.transactionLink } }];
